#!/usr/bin/env python3
"""Summarize fixed-input diagnostics; never executes a selector or opens a DB."""
import json,pathlib,statistics,hashlib
HERE=pathlib.Path(__file__).resolve().parent
load=lambda n:json.loads((HERE/n).read_text())
def detailed_reads(r):
 groups={}
 for row in r['rawReadCalls']:
  key=f"{row['method']}:{row['args'][0]}";g=groups.setdefault(key,{'calls':0,'keys':set(),'elapsedMs':0})
  g['calls']+=1;g['keys'].add(row['key']);g['elapsedMs']+=row['elapsedMs']
 return {k:{'calls':v['calls'],'uniqueKeys':len(v['keys']),'elapsedMs':v['elapsedMs']} for k,v in groups.items()}
s=load('comparison-summary.json');ex=load('comparison-execution.json');assert ex['error'] is None
negative={mode:load(mode+'.json') for mode in ['sqlite','memory']};controlled={mode:load('controlled-'+mode+'.json') for mode in ['sqlite','memory']};patched=load('patched-cursor.json')
details={name:[detailed_reads(load(f'pair-{i}-{order}-{name}.json')) for i in range(1,4)] for order,name in enumerate(['baseline','current'],1)}
readMedians={name:{key:{'calls':rows[0][key]['calls'],'uniqueKeys':rows[0][key]['uniqueKeys'],'medianMs':statistics.median(r[key]['elapsedMs'] for r in rows)} for key in rows[0]} for name,rows in details.items()}
rss={name:statistics.median(s[name]['maxRSS']) for name in ['baseline','current']}
costs={'maxRssKiBMedian':rss,'maxRssDeltaMiB':(rss['current']-rss['baseline'])/1024,'maxRssDeltaPercent':(rss['current']/rss['baseline']-1)*100,'inputTaskBytesEqual':s['baseline']['byteCounts']['inputTask']==s['current']['byteCounts']['inputTask'],'resultTaskBytesEqual':s['baseline']['byteCounts']['resultTask']==s['current']['byteCounts']['resultTask'],'storageBenefitClaimed':False,'limits':'Process high-water RSS includes unique material retention, post-timing byte accounting and serialization. Version difference is retained as a negative result; these data do not locate selector peak/production heap or attribute the entire increase to caches.'}
data={'protocol':'run7-route-selection-fixed-counterfactual-report-v1','revisions':ex['revisions'],'negativeFinalTask':{k:{'timingsMs':v['timingsMs'],'selected':v['selectedSummary'],'events':v['events']} for k,v in negative.items()},'cursorControlled':{k:{'timingsMs':v['timingsMs'],'detailedReads':detailed_reads(v),'selected':v['selectedSummary'],'events':v['events']} for k,v in controlled.items()},'patchedCursor':{'timingsMs':patched['timingsMs'],'detailedReads':detailed_reads(patched)},'freshDeferrals':s,'freshDetailedReads':details,'profile':load('profile-summary.json'),'execution':ex,
 'groupedReadMedians':readMedians,'costs':costs,'limits':['No exact pre-selection task snapshot exists. Final task is never represented as historical pre-state.','Cursor controlled changes only scheduling.cursor using actual sequence4918; fresh-deferrals also empties scheduling.deferred. All routeRetries, final failed route, plan rows, evidence, unknown fields and pause state are retained.','Read-only selector with memory event sink. Complete submitted event payloads are compared in order; the sink adds no wall-clock at or SQLite sequence. No actual SDK recovery, provider/browser, task-event SQLite writes, or total real-run performance claim.','RawReturns retains first complete result per unique read key (128.65 MB material in cursor case). Peak process RSS includes this instrumentation and serialization, not production eight-entry LRU usage. The observed RSS increase remains a negative comparison result and is not attributed entirely to cache changes.','Absolute times may include GC and profile perturbation; only three unprofiled AB pairs form the paired summary.','The actual fixed task has no active unknown attempts. Unknown behavior is established by separate product/protocol tests, not invented here.']}
(HERE/'summary.json').write_text(json.dumps(data,indent=2)+'\n')
base=s['baseline'];cur=s['current'];pct=(1-s['ratio'])*100
def seconds(x):return f'{x/1000:.3f}'
lines=['# Run 7 route-selection diagnostic','',f"The fixed `069b65b` → `cbd5b87` comparison preserves the complete selected result, task and ordered events in all {len(ex['comparisons'])} cross/within-version comparisons. Three serial fresh-process pairs show selector median **{seconds(base['medianMs'])} → {seconds(cur['medianMs'])} seconds ({pct:.2f}% reduction)**. This is a controlled selector measurement, not a speed claim for the complete live run.",'','## Input and historical-state boundary','',
'The live scope.audit sequence 5138 (00:55:36.104 UTC) to recovery.selected sequence 5369 (00:56:20.084) lasted 43.980 seconds. That bracket also includes obligation reconciliation, local ordering and persistence. ExplorerStore stores the latest task, not full historical task versions. The logs do not justify blindly deleting the last failed route to reproduce the original selected item.','',
'The first negative sample deliberately uses the unmodified final task with the actual earlier observation `f6ad38c2-acb1-4801-9edb-6ec802ce8ae7` and recorded availability. Its already-advanced cursor skips the expensive sweep: SQLite 141.190 ms versus memory 89.478 ms. This sample is retained and is **not** evidence that the original 44-second cost disappeared.','',
'The cursor-controlled case changes exactly `task.scheduling.cursor` to `5480402f-ee64-49fc-9f3e-1cfe5ffce00f`, copied from the actual last current selection (sequence 4918). The fresh-deferrals case additionally clears only `scheduling.deferred`, the scan-reason cache. Neither case deletes or resets routeRetries, unknown debt, the final failed route, plan occurrences or retained sources. Both are explicit counterfactuals, not exact history reconstruction.','',
'The final failed route prevents assuming the original selected item. The controlled selector actually chooses `53cc4e09-7c99-43e6-bb57-272e46dbc6b3`, source `5f80a3df-8355-444a-8499-4a625cb89577`, checkpoint `b1e80845-ab4f-4c31-809d-ba37be180e92`; this complete choice is compared, not patched to match the live selection.','',
'## Cost attribution','',
'The cursor-controlled baseline takes 38.970 seconds with CPU profiling, versus 8.795 seconds with the exact same material served in memory. The complete outputs match. Timed readonly reads comprise 1,947 observation reads / 33 unique keys (24.276 seconds), 1,948 session reads / one key (0.111 seconds), and 656 action-list reads / 32 keys (0.462 seconds). These are real JSON/codec read costs in the isolated copy; the comparison must not attribute them all to scope projection.','',
'The original production read methods and eight-entry scheduler LRU remain in the experiment. No SqliteStore or BrowserEngine constructor, migration or mutation runs. Only the ObservationObjectStore reader/cache and pure interactionTransition method are used. SQLite is readonly/query_only and total_changes is zero. The memory event sink records complete submitted payloads in order; it adds no wall-clock timestamp or SQLite sequence, and event SQL writes are outside this experiment.','',
'Formal fresh-deferrals timings (unprofiled, serial AB order):','',
'| Pair | 069 baseline seconds | cbd current seconds |','|---|---:|---:|']
for i,(a,b) in enumerate(zip(base['samplesMs'],cur['samplesMs']),1):lines.append(f'| {i} | {seconds(a)} | {seconds(b)} |')
lines+=['',f"Median ratio: {s['ratio']:.6f}. All comparison gates precede summary aggregation. The cursor case emits {controlled['sqlite']['events']['count']} events; fresh-deferrals emits {base['events']['count']} events in both versions.",'',
'Formal fresh-deferrals grouped readonly cost (medians; counts stable across all three samples):','',
'| Read | Baseline calls / unique keys | Current calls / unique keys | Baseline seconds | Current seconds |','|---|---:|---:|---:|---:|']
for key in ['require:observation','require:session','listByObservation:action','list:checkpoint']:
 a,b=readMedians['baseline'][key],readMedians['current'][key]
 lines.append(f"| {key} | {a['calls']} / {a['uniqueKeys']} | {b['calls']} / {b['uniqueKeys']} | {seconds(a['medianMs'])} | {seconds(b['medianMs'])} |")
lines+=['',f"**Negative memory result:** process maxRSS median rises from {rss['baseline']:,} KiB to {rss['current']:,} KiB: **+{costs['maxRssDeltaMiB']:.1f} MiB / +{costs['maxRssDeltaPercent']:.1f}%**. Both versions retain the same unique material for diagnostics, but this does not erase the measured version difference. The high-water mark also includes byte accounting and full-result serialization after the timed selector; it is neither production heap nor an isolated selector peak. These data cannot attribute the entire increase to the new caches.",'',
f"Input task JSON is {base['byteCounts']['inputTask']:,} bytes and resulting task JSON is {base['byteCounts']['resultTask']:,} bytes, exactly equal across versions. **No storage saving is claimed.**",'',
'The source-read bottleneck remains. The optimization does not expand the raw-source cache, delete audit history or change recovery permission. Full read counts and per-method timing are retained in summary.json and every trial report. Further changes to sharing during one synchronous SDK read require a separate contract and measurement.','',
'## Integrity and reproduction','',
'- Exact source archives: `069b65b47d951cdcced4d895e2abe33738267e5a` and `cbd5b878329f8d3e454e8fd5110d0e2da4f749a7`; workspace dependencies resolve inside each archive. External installed packages are read-only.','- Input: complete owned copy of frozen-7, with engine/plugin DB SHA checked before and after; original active DB is never opened. Archive and raw input checks remain unchanged.','- Every complete semantic artifact is saved losslessly under semantic-objects, addressed by logical JSON SHA; semantic-artifact-index.json maps each original trial filename. Complete task/choice/events are compared without dropping IDs, debt, order or fields.','- Raw CPU profiles and profile-summary.json remain diagnostic. Inclusive samples overlap and cannot be added.','',
'Execution order: runner.py --run; controlled-runner.py (prepare), controlled-runner.py --run; controlled-runner.py --case fresh-deferrals (prepare); compare-runner.py --run; profile-summary.py; archive-semantic.py; make-report.py. Scripts refuse to overwrite executed result directories. Reproduction requires Node 24.22.0, installed workspace/external dependencies, Git archives and the complete frozen-7 directory. setup.json records the private copy/archive/input locations. Initial task material is rebuilt from frozen run/task-after.json plus scope.audit from metrics.jsonl; controlled-preparation.json records the sole cursor substitution. No temporary material/database must be committed.','',
'Peak RSS belongs to the diagnostic worker: it retains every unique first returned value to save the exact material (128.65 MB in the controlled case), then serializes full results. It does not measure the production eight-source cache footprint. Import, setup, byte accounting and output serialization are outside selector clocks. All actual plan rows and failed route debt are retained; the fixture contains no active unknown attempt, so separate unknown/debt product tests remain necessary.','']
(HERE/'report.md').write_text('\n'.join(lines))
manifest=[{'path':str(p.relative_to(HERE)),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(HERE.rglob('*')) if p.is_file() and p.name!='artifact-manifest.json']
(HERE/'artifact-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'summary':hashlib.sha256((HERE/'summary.json').read_bytes()).hexdigest(),'report':hashlib.sha256((HERE/'report.md').read_bytes()).hexdigest(),'files':len(manifest),'bytes':sum(r['bytes'] for r in manifest)}))
